 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    pts = [(r, c, out[r][c]) for r in range(h) for c in range(w) if out[r][c] != 0]
    one = next(((r,c) for r,c,v in pts if v == 1), None)
    two = next(((r,c) for r,c,v in pts if v == 2), None)
