    # This also naturally leaves any other colored markers untouched.
    for cc in range(c1+1, c1+3):
        if 0 <= cc < w and out[r1][cc] == 0:
            out[r1][cc] = 5
    span = abs(r2-r1) + abs(c2-c1) - 1
    if span < 1:
        span = 1
    left = c2 - span//2
