        if 0 <= cc < w and out[r2][cc] == 0:
            out[r2][cc] = 5
    # Fill the vertical connector from the 1's bar down toward the 2 row.
    for rr in range(r1+1, r2):
        if 0 <= rr < h and 0 <= c1+2 < w and out[rr][c1+2] == 0:
            out[rr][c1+2] = 5
    return out
