                out[rr][cc] = value

    # 2 motif: a horizontal 2-5-5-5-2 bar, plus rightward 5s in certain contexts.
    if two:
        r, c = two
        for cc, value in ((c-4,2),(c-3,5),(c-2,5),(c-1,5),(c+1,5),(c+2,5)):
