 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    seeds = [(r, c, out[r][c]) for r in range(h) for c in range(w) if out[r][c] != 0]
    one = next(((r, c) for r, c, v in seeds if v == 1), None)
    two = next(((r, c) for r, c, v in seeds if v == 2), None)
    three = next(((r, c) for r, c, v in seeds if v == 3), None)
    six = next(((r, c) for r, c, v in seeds if v == 6), None)

    def put(r, c, value, force=False):
        if 0 <= r < h and 0 <= c < w and (force or out[r][c] == 0):
            out[r][c] = value

    # A 1 creates a short rightward bar and a duplicate 1 above its tip.
    if one:
        r, c = one
        put(r, c + 1, 5)
        put(r, c + 2, 5)
        put(r - 1, c + 2, 1)

    # A 2 creates a horizontal pattern: 2, three 5s, then the original 2;
    # there are two more 5s to the right when that side is unobstructed.
    if two:
        r, c = two
        for cc, value in ((c - 4, 2), (c - 3, 5), (c - 2, 5), (c - 1, 5),
                          (c + 1, 5), (c + 2, 5)):
            put(r, cc, value)
        if six is None and not (three and three == (r + 1, c + 2)):
            put(r, c + 3, 5)
            put(r, c + 4, 5)

    # A 3 extends downward three cells, with 3 at the far endpoint.
    if three:
        r, c = three
        for rr, value in ((r + 1, 5), (r + 2, 5), (r + 3, 3)):
            put(rr, c, value)

    # A 6 extends six cells upward; the far endpoint is another 6.
    if six:
        r, c = six
        top = max(0, r - 6)
        for rr in range(top + 1, r):
            put(rr, c, 5)
        if top < r:
            put(top, c, 6, force=True)

    # When the 2 bar crosses a 3- or 6-ray, mark the intersection 4 and
    # continue diagonally down-left in 4s.
    if two:
        r, c = two
        cross_col = None
        if six and c - 4 <= six[1] <= c + 2 and six[0] > r:
