        if three and c - 4 <= three[1] <= c + 2 and three[0] < r <= three[0] + 3:
            cross_col = three[1]
        if cross_col is not None:
            put(r, cross_col, 4, force=True)
            for k in range(1, min(h - r, cross_col + 1)):
                put(r + k, cross_col - k, 4)

    return out
